def timecode(seconds):
    return f"{seconds // 60}:{seconds % 60:02d}"

def shots():
    start = 0
    for index, (end, data) in enumerate(zip(SHOT_ENDS, SHOT_TEXT), 1):
        key, camera, action = data
        yield dict(id=index, start=start, end=end, frame=key, camera=camera, action=action)
        start = end

def validate():
    assert len(FRAMES) == 18 and len(SHOT_ENDS) == len(SHOT_TEXT) == 36
    assert SHOT_ENDS[-1] == 300
    assert all(a < b for a,b in zip([0]+SHOT_ENDS[:-1], SHOT_ENDS))
    assert FRAMES[0]['start'] == 0 and FRAMES[-1]['end'] == 300
    assert all(a['end'] == b['start'] for a,b in zip(FRAMES, FRAMES[1:]))
    assert len({(x['sheet'],x['cell']) for x in FRAMES}) == 18
    assert all(x['frame'] in {f['id'] for f in FRAMES} for x in shots())
